&lt;li&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;TextRun SCXW240234066 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW240234066 BCX8&quot;&gt;&lt;span class=&quot;TextRun SCXW96905513 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW96905513 BCX8&quot;&gt;Work closely with Hiring Managers to understand what they are looking for and adjust your approach accordingly.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW96905513 BCX8&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;TextRun SCXW240234066 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW240234066 BCX8&quot;&gt;&lt;span class=&quot;TextRun SCXW172011210 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW172011210 BCX8&quot;&gt;Represent thinkcell at technical events, conferences, meetups, and universities to expand our talent pipeline. &lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW172011210 BCX8&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;TextRun SCXW240234066 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW240234066 BCX8&quot;&gt;&lt;span class=&quot;TextRun SCXW245316862 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW245316862 BCX8&quot;&gt;Maintain a high bar for quality while filling roles efficiently in a competitive global market.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW245316862 BCX8&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;TextRun SCXW240234066 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW240234066 BCX8&quot;&gt;&lt;span class=&quot;TextRun SCXW63691822 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW63691822 BCX8&quot;&gt;Help shape our employer branding in the tech space, refining messaging and outreach strategies.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You will be great for this position if you have&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
